import {exercises,exerciseById,groups,alternatives,equipmentLabels} from './data.js';
import {workSets,performance,e1rm,progression,within} from './science.js';
import {esc,icon,btn,empty,field,select,num,dateLabel,modal,toast,chart} from './ui.js';
import {TODAY,uid} from './store.js';
export const newSet=(reps=0,load=0)=>({id:uid(),reps,load,duration:0,distance:0,resistance:'',rpe:null,rir:null,warmup:false,done:false});
export const itemFor=(id,sets=3,reps=10)=>({id:uid(),exerciseId:id,sets:Array.from({length:sets},()=>newSet(reps)),targetReps:reps,superset:'',notes:''});
export async function startWorkout(C,routineId){if(C.state.draft){location.hash='training';toast('Your unfinished workout is ready');return}const routine=C.state.routines.find(r=>r.id===routineId);C.state.draft={id:uid(),name:routine?.name||'New workout',date:TODAY(),startedAt:Date.now(),exercises:(routine?.exercises||[]).map(e=>itemFor(e.exerciseId,e.sets,e.reps)),notes:'',restSeconds:routine?.restSeconds||120};await C.save('Workout started');location.hash='training'}
const input=(value,attrs)=>`<input value="${esc(value??'')}" ${attrs}>`;
export function trainingView(C){const {state}=C,d=state.draft;return `<div class="page-head"><div><div class="eyebrow">Strength & movement</div><h1>${d?'Your workout':'Training'}</h1><p>${d?'Log the work. Keep the detail that matters.':'Routines, sessions, and progress in one place.'}</p></div><div class="button-group">${d?btn('Finish workout','finish-workout','primary','check'):btn('Start workout','start-workout','primary','plus')}${btn('Create routine','routine-new')}</div></div>${d?draftView(C,d):`<div class="grid equal"><section class="card"><div class="card-head"><h2>Your routines</h2>${btn('New','routine-new','small','plus')}</div>${state.routines.length?state.routines.map(r=>`<div class="row"><div><strong>${esc(r.name)}</strong><p>${r.exercises.length} exercises · ${r.exercises.reduce((a,e)=>a+e.sets,0)} planned sets</p></div><div class="row-actions">${btn('Start','start-routine:'+r.id,'small primary')}${btn('Edit','routine-edit:'+r.id,'small')}</div></div>`).join(''):empty('A plan makes starting easier','Create a routine or choose a plan based on your equipment.','go-plan','Build a plan')}</section><section class="card"><div class="card-head"><h2>Session history</h2><span class="badge">${state.sessions.length} sessions</span></div>${state.sessions.length?sessionRows(state.sessions):empty('Your first session is ahead','Start a workout and add movements from the exercise library.','start-workout','Start a workout')}</section></div><section class="card subsection"><div class="card-head"><h2>Exercise performance</h2></div>${select('performance-ex','Choose an exercise',C.ui.performanceExercise||exercises[0].id,exercises.filter(e=>e.category==='strength').map(e=>[e.id,e.name]))}<div id="performance-panel">${performancePanel(C,C.ui.performanceExercise||exercises[0].id)}</div></section>`}`}
function draftView(C,d){return `<div class="live-banner"><span><strong>Workout in progress</strong> · ${d.exercises.length} exercises</span><span class="meta">Autosaved locally</span></div><section class="card" style="margin-bottom:22px"><div class="form-grid">${field('session-name','Session name',d.name,'text','maxlength="100" data-draft-field="name" required')}${field('session-date','Date',d.date,'date','data-draft-field="date" required max="'+TODAY()+'"')}${field('restSeconds','Rest timer (seconds)',d.restSeconds,'number','min="0" max="1800" data-draft-field="restSeconds"')}${field('session-notes','Session notes',d.notes,'text','maxlength="1000" data-draft-field="notes"')}</div><div class="button-group">${btn('Add exercise','pick-exercise','primary','plus')}${btn('Start rest timer','timer:'+d.restSeconds,'','time')}${btn('Save as routine','draft-to-routine')}${btn('Discard workout','discard-workout','danger')}</div><p class="unit-note">Loads are recorded in ${C.loadUnit()}. Use the total external load you intend to compare; record per-hand, assisted, or machine conventions in exercise notes. No body mass is inferred. For unilateral movements, one set row represents a completed left/right pair; record side-specific observations in notes.</p></section>${d.exercises.map(item=>exerciseEditor(C,item)).join('')}${!d.exercises.length?empty('Choose your first movement','Search the library to add an exercise. You can log repetitions, load, effort, time, and distance.','pick-exercise','Add exercise'):''}`}
function exerciseEditor(C,item){const e=exerciseById(item.exerciseId);return `<section class="card session-exercise"><div class="card-head"><div><h2>${esc(e.name)}</h2><p class="meta" style="margin:5px 0 0">${e.primary.map(g=>groups.find(x=>x.id===g)?.name).join(' · ')||e.category} · ${item.sets.filter(s=>s.done).length}/${item.sets.length} sets complete</p></div><div class="button-group">${btn('Details','exercise:'+e.id,'small')}${btn('Swap','swap-exercise:'+item.id,'small')}${btn('Remove','remove-draft-exercise:'+item.id,'small danger')}</div></div><div class="table-wrap"><table class="data-table set-table"><thead><tr><th>Set</th><th>${C.loadUnit()}</th><th>Reps</th><th>Seconds</th><th>Metres</th><th>RPE</th><th>RIR</th><th>Warm-up</th><th>Done</th><th></th></tr></thead><tbody>${item.sets.map((s,i)=>`<tr data-item="${item.id}" data-set="${s.id}"><td>${i+1}</td>${['load','reps','duration','distance','rpe','rir'].map(key=>`<td>${input(key==='load'?C.displayLoad(s[key]):s[key],`type="number" aria-label="${esc(e.name)} set ${i+1} ${key}" data-set-field="${key}" min="${key==='rpe'?1:0}" max="${key==='rpe'?10:key==='rir'?10:key==='reps'?1000:key==='load'?2000:key==='duration'?86400:100000}" step="${['load','rpe'].includes(key)?'.5':'1'}"`)}</td>`).join('')}<td><input type="checkbox" data-set-field="warmup" aria-label="Set ${i+1} warm-up" ${s.warmup?'checked':''}></td><td><input type="checkbox" data-set-field="done" aria-label="Complete set ${i+1}" ${s.done?'checked':''}></td><td>${btn('×','remove-set:'+item.id+'|'+s.id,'small ghost')}</td></tr>`).join('')}</tbody></table></div><div class="button-group" style="margin:14px 0 20px">${btn('Add set','add-set:'+item.id,'small','plus')}${btn('Rest '+C.state.draft.restSeconds+'s','timer:'+C.state.draft.restSeconds,'small','time')}</div><div class="form-grid">${field('group-'+item.id,'Superset / circuit label',item.superset,'text',`maxlength="30" placeholder="e.g. A or Circuit 1" data-item-field="superset" data-item="${item.id}"`)}${field('notes-'+item.id,'Exercise notes / resistance',item.notes,'text',`maxlength="500" data-item-field="notes" data-item="${item.id}"`)}</div><p class="meta">RPE and RIR are subjective. RPE 10 ≈ 0 RIR, 9 ≈ 1 RIR, 8 ≈ 2 RIR. Use one or both; inconsistent pairs are rejected.</p></section>`}
export function sessionRows(sessions){return [...sessions].sort((a,b)=>b.date.localeCompare(a.date)).map(s=>`<div class="row"><div><strong>${esc(s.name)}</strong><p>${dateLabel(s.date)} · ${s.exercises.reduce((a,e)=>a+workSets(e).length,0)} working sets · ${s.exercises.length} exercises</p></div>${btn('View','session:'+s.id,'small')}</div>`).join('')}
export function performancePanel(C,id){const e=exerciseById(id),h=performance(C.state.sessions,id),est=h.filter(p=>p.e1rm!==null),p=progression(C.state.sessions,id,12),volume=h.reduce((a,x)=>a+x.volume,0);return `<div class="metrics" style="grid-template-columns:repeat(3,1fr)"><div><div class="meta">Best recorded load</div><div class="large-number">${h.length?num(C.displayLoad(Math.max(...h.map(p=>p.load))),1):'—'} <small>${C.loadUnit()}</small></div></div><div><div class="meta">Best estimated 1RM</div><div class="large-number">${est.length?num(C.displayLoad(Math.max(...est.map(p=>p.e1rm))),1):'—'} <small>${C.loadUnit()}</small></div></div><div><div class="meta">Sessions</div><div class="large-number">${h.length}</div></div></div>${chart(h.map(p=>({date:p.date,value:C.displayLoad(p.load)})),{unit:'Best recorded load ('+C.loadUnit()+')'})}<div class="notice" style="margin-top:22px"><strong>Progression check · target 12 reps</strong><p>${esc(p.message)}</p>${p.ready?`<p>Illustrative next load: ${num(C.displayLoad(p.load),1)} ${C.loadUnit()}. Round to available equipment.</p>`:''}<small>App heuristic; never applied automatically. ${C.sourceLinks(['acsm2026','acsm2009'])}</small></div><p class="footer-note">Epley estimates use completed, non-warm-up sets of 2–10 reps with 0 RIR. Only an explicitly maximal-effort (0 RIR) single is shown directly. Estimates and load suggestions are suppressed for assistance, bands, bodyweight, machines, cables and timed movements. This is exercise-specific and imperfect; missing effort or higher-rep sets do not produce an estimate. ${C.sourceLinks(['epley_formula2019','reynolds2006'])}</p>`}
export function picker(C,onChoose,filter=null){const d=modal('Choose an exercise',`<div class="field"><label for="exercise-search">Search movements</label><input id="exercise-search" placeholder="Name, muscle, equipment"></div><div id="pick-results"></div>`,()=>{});d.querySelector('.modal-footer').remove();const list=filter||exercises;const paint=q=>{d.querySelector('#pick-results').innerHTML=list.filter(e=>(e.name+' '+e.aliases+' '+e.primary.map(g=>groups.find(x=>x.id===g)?.name)+' '+e.equipment).toLowerCase().includes(q.toLowerCase())).map(e=>`<div class="row"><div><strong>${esc(e.name)}</strong><p>${e.equipment.map(x=>equipmentLabels[x]).join(' · ')}</p></div><button type="button" class="btn small" data-pick="${e.id}">Choose</button></div>`).join('')||empty('No matching exercises','Try a different name or equipment.');d.querySelectorAll('[data-pick]').forEach(b=>b.onclick=async()=>{await onChoose(b.dataset.pick);d.close()})};d.querySelector('#exercise-search').oninput=e=>paint(e.target.value);paint('')}
export function routineDialog(C,id='',fromDraft=false){const r=C.state.routines.find(r=>r.id===id)||{name:fromDraft?C.state.draft.name:'',restSeconds:120,exercises:fromDraft?C.state.draft.exercises.map(e=>({exerciseId:e.exerciseId,sets:e.sets.length,reps:e.targetReps||10})):[]};const d=modal(id?'Edit routine':'Create routine',`${field('name','Routine name',r.name,'text','required maxlength="100"')}${field('rest','Rest between sets (seconds)',r.restSeconds,'number','required min="0" max="1800"')}<p class="meta">Choose movements and set targets. You can change every set during a workout.</p><div class="field"><label for="routine-search">Filter exercises</label><input id="routine-search" placeholder="Search movements"></div><div id="routine-list">${exercises.map(e=>{const v=r.exercises.find(x=>x.exerciseId===e.id);return `<div class="row" data-routine-name="${esc(e.name.toLowerCase())}"><label class="check" style="margin:0;flex:1"><input type="checkbox" name="exercise" value="${e.id}" ${v?'checked':''}>${esc(e.name)}</label><div style="display:flex;gap:8px"><input name="sets-${e.id}" type="number" min="1" max="20" value="${v?.sets||3}" aria-label="${esc(e.name)} target sets" style="width:55px;padding:7px"><input name="reps-${e.id}" type="number" min="1" max="100" value="${v?.reps||10}" aria-label="${esc(e.name)} target reps" style="width:55px;padding:7px"></div></div>`}).join('')}</div>`,async fd=>{const ids=fd.getAll('exercise');if(!ids.length)throw Error('Choose at least one exercise.');const updated={id:id||uid(),name:fd.get('name').trim(),restSeconds:Number(fd.get('rest')),exercises:ids.map(exerciseId=>({exerciseId,sets:Number(fd.get('sets-'+exerciseId)),reps:Number(fd.get('reps-'+exerciseId))}))};if(!updated.name)throw Error('Enter a routine name.');if(id)C.state.routines=C.state.routines.map(x=>x.id===id?updated:x);else C.state.routines.push(updated);await C.save('Routine saved')});d.querySelector('#routine-search').oninput=e=>d.querySelectorAll('[data-routine-name]').forEach(r=>r.hidden=!r.dataset.routineName.includes(e.target.value.toLowerCase()));if(id){const b=document.createElement('button');b.type='button';b.className='btn danger';b.textContent='Delete routine';b.onclick=()=>C.confirm('Delete this routine?','Scheduled entries using it will be removed. Workout history stays available.',async()=>{C.state.routines=C.state.routines.filter(x=>x.id!==id);C.state.schedule=C.state.schedule.filter(x=>x.routineId!==id);await C.save('Routine deleted')});d.querySelector('.modal-footer').prepend(b)}}
export function sessionDialog(C,id){const s=C.state.sessions.find(x=>x.id===id);if(!s)return;const d=modal(s.name,`<p class="meta">${dateLabel(s.date)}${s.durationMinutes?' · '+num(s.durationMinutes)+' min':''}</p>${s.exercises.map(item=>{const e=exerciseById(item.exerciseId);return `<h3>${esc(e?.name||item.exerciseId)}</h3>${item.superset?`<p class="meta">Group: ${esc(item.superset)}</p>`:''}<div class="table-wrap"><table class="data-table"><thead><tr><th>Set</th><th>Load</th><th>Reps</th><th>Time / distance</th><th>RIR</th><th>Type</th></tr></thead><tbody>${item.sets.filter(x=>x.done).map((x,i)=>`<tr><td>${i+1}</td><td>${num(C.displayLoad(x.load),1)} ${C.loadUnit()}</td><td>${num(x.reps)}</td><td>${x.duration?num(x.duration)+'s ':''}${x.distance?num(x.distance)+'m':''}</td><td>${x.rir??'—'}</td><td>${x.warmup?'Warm-up':'Working'}</td></tr>`).join('')}</tbody></table></div>${item.notes?`<p class="note-box">${esc(item.notes)}</p>`:''}`}).join('')}${s.notes?`<p class="notice">${esc(s.notes)}</p>`:''}<div class="button-group">${btn('Duplicate','duplicate-session:'+id)}${btn('Edit session','edit-session:'+id)}${btn('Delete','delete-session:'+id,'danger')}</div>`,()=>{});d.querySelector('.modal-footer').remove()}
export async function trainingAction(a,id,C){const d=C.state.draft;if(a==='start-workout'){await startWorkout(C);return true}if(a==='start-routine'){await startWorkout(C,id);return true}if(a==='routine-new'){routineDialog(C);return true}if(a==='routine-edit'){routineDialog(C,id);return true}if(a==='draft-to-routine'){routineDialog(C,'',true);return true}if(a==='pick-exercise'){picker(C,async id=>{d.exercises.push(itemFor(id));await C.save('Exercise added')});return true}if(a==='swap-exercise'){const item=d.exercises.find(e=>e.id===id);picker(C,async ex=>{item.exerciseId=ex;item.sets=[newSet()];await C.save('Exercise substituted')},alternatives(exerciseById(item.exerciseId),C.state.profile.equipment));return true}if(a==='add-set'){const item=d.exercises.find(e=>e.id===id),last=item.sets.at(-1);item.sets.push({...newSet(last?.reps||0,last?.load||0),rir:last?.rir??null});await C.save('Set added');return true}if(a==='remove-set'){const [itemId,setId]=id.split('|');d.exercises.find(e=>e.id===itemId).sets=d.exercises.find(e=>e.id===itemId).sets.filter(s=>s.id!==setId);await C.save('Set removed');return true}if(a==='remove-draft-exercise'){C.confirm('Remove this exercise?','Its sets will be removed from this unfinished workout.',async()=>{d.exercises=d.exercises.filter(e=>e.id!==id);await C.save('Exercise removed')});return true}if(a==='discard-workout'){C.confirm('Discard this workout?','The unfinished sets will be deleted.',async()=>{C.state.draft=null;await C.save('Workout discarded')});return true}if(a==='finish-workout'){if(!d.exercises.some(e=>workSets(e).length||e.sets.some(s=>s.done&&s.warmup)))throw Error('Complete at least one set before saving the session.');if(!d.name.trim())throw Error('Enter a session name.');if(d.date>TODAY())throw Error('Choose today or an earlier date.');C.validateDraft(d);const session=structuredClone(d);session.exercises=session.exercises.filter(e=>e.sets.some(s=>s.done)).map(e=>({...e,sets:e.sets.filter(s=>s.done)}));session.durationMinutes=Math.max(1,Math.round((Date.now()-d.startedAt)/60000));if(d.editingId){session.id=d.editingId;C.state.sessions=C.state.sessions.map(s=>s.id===d.editingId?session:s)}else C.state.sessions.push(session);C.state.draft=null;await C.save('Workout saved');return true}if(a==='session'){sessionDialog(C,id);return true}if(a==='duplicate-session'||a==='edit-session'){if(d)throw Error('Finish or discard your current workout first.');const s=structuredClone(C.state.sessions.find(s=>s.id===id));s.startedAt=Date.now();if(a==='duplicate-session'){s.id=uid();s.date=TODAY();s.name+=' · repeat';s.exercises.forEach(e=>e.sets.forEach(x=>x.done=false))}else s.editingId=id;C.state.draft=s;document.querySelector('#modal').close();location.hash='training';await C.save(a==='edit-session'?'Session ready to edit':'Workout duplicated');return true}if(a==='delete-session'){C.confirm('Delete this session?','This removes it from your history and muscle analytics.',async()=>{C.state.sessions=C.state.sessions.filter(s=>s.id!==id);await C.save('Session deleted')});return true}return false}
export async function trainingInput(e,C){const el=e.target;if(el.dataset.draftField){const key=el.dataset.draftField;C.state.draft[key]=key==='restSeconds'?Number(el.value):el.value;await C.persist();return true}if(el.dataset.itemField){C.state.draft.exercises.find(x=>x.id===el.dataset.item)[el.dataset.itemField]=el.value;await C.persist();return true}if(el.dataset.setField){const tr=el.closest('[data-set]'),s=C.state.draft.exercises.find(x=>x.id===tr.dataset.item).sets.find(x=>x.id===tr.dataset.set),key=el.dataset.setField;s[key]=el.type==='checkbox'?el.checked:el.value===''?null:key==='load'?C.parseLoad(Number(el.value)):Number(el.value);await C.persist();return true}if(el.name==='performance-ex'){C.ui.performanceExercise=el.value;document.querySelector('#performance-panel').innerHTML=performancePanel(C,el.value);return true}return false}

